package com.bank.volume;

import java.util.ArrayDeque;
import java.util.Deque;

// Largest rectangle under a histogram using an increasing index stack.
public class HistogramRectangleFinder {

    public long largestRectangle(int[] heights) {
        int n = heights.length;
        long maxArea = 0;
        Deque<Integer> stack = new ArrayDeque<>(); // indices, increasing heights

        // Iterate one past the end; a virtual bar of height 0 flushes the stack.
        for (int i = 0; i <= n; i++) {
            int current = (i == n) ? 0 : heights[i];
            // A shorter current bar closes all taller pending bars.
            while (!stack.isEmpty() && current < heights[stack.peek()]) {
                int height = heights[stack.pop()];
                // Width spans from the bar after the new top up to i.
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;
                maxArea = Math.max(maxArea, (long) height * width);
            }
            stack.push(i);
        }
        return maxArea;
    }
}
