package com.bank.volume;

import java.util.Arrays;
import java.util.logging.Logger;

// Reports the largest sustained-volume block from an hourly histogram.
public class VolumeAnalyticsService {

    private static final Logger log = Logger.getLogger(VolumeAnalyticsService.class.getName());
    private final HistogramRectangleFinder finder;

    public VolumeAnalyticsService(HistogramRectangleFinder finder) {
        this.finder = finder;
    }

    public long largestSustainedBlock(int[] hourlyVolumes) {
        long area = finder.largestRectangle(hourlyVolumes);
        log.info(() -> "Volumes " + Arrays.toString(hourlyVolumes)
                + " largest sustained block (area) = " + area);
        return area;
    }
}
