package com.bank.volume;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class HistogramDemo {

    private static final Logger log = Logger.getLogger(HistogramDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Largest Sustained Volume Block");
        VolumeAnalyticsService service =
                new VolumeAnalyticsService(new HistogramRectangleFinder());

        int[] hourlyVolumes = {2, 1, 5, 6, 2, 3};
        // Largest rectangle: bars of height 5 and 6 → width 2 × height 5 = 10
        service.largestSustainedBlock(hourlyVolumes);
    }
}
